    /// <summary>
    /// MPJ_4054_CustAgingReport
    /// </summary>
    /// <param name="args">
    /// get the CustAgingReport class 
    /// </param>
    [PostHandlerFor(classStr(CustAgingReportDP), methodStr(CustAgingReportDP, processReport))]
    public static void CustAgingReportDP_Post_processReport(XppPrePostArgs args)
    {
        CustAgingReportDP       metCustAgingReportDP    =   args.getThis() as CustAgingReportDP;
        CustAgingReportTmp      metCustAgingReportTmp   =   metCustAgingReportDP.getCustAgingReportTmp();
        METCustTable            metCustTable;
        CustTrans               metCustTrans;
        CustVendDisputeHelper   metDisputeHelper;

        while select forupdate metCustAgingReportTmp
        {
            ttsbegin;

            select firstonly AccountNum,IndustryKey from metCustTable
                where metCustTable.AccountNum == metCustAgingReportTmp.AccountNum;

            metCustAgingReportTmp.METIndustryKey = metCustTable.IndustryKey;

            select sum(AmountCur),sum(SettleAmountMST) from metCustTrans
                where metCustTrans.AccountNum == metCustAgingReportTmp.AccountNum
                &&    metCustTrans.TransType    == LedgerTransType::Payment;

            metCustAgingReportTmp.METUnallocatedCash = metCustTrans.AmountCur - metCustTrans.SettleAmountMST;

           
            select firstonly AccountNum from metCustTrans
                where metCustTrans.AccountNum == metCustAgingReportTmp.AccountNum;

            metDisputeHelper = CustVendDisputeHelper::construct(metCustTrans.company(), tablenum(CustTrans), metCustTrans.RecId);

            if(metDisputeHelper.parmStatus() == CustVendDisputeStatus::Disputed)
            {
                metCustAgingReportTmp.METTotalInDispute =  metDisputeHelper.parmAmountCur();
            }
            metCustAgingReportTmp.METTotalOverDue = (metCustAgingReportTmp.Balance03 + metCustAgingReportTmp.Balance04 + metCustAgingReportTmp.Balance05 +
                                                     metCustAgingReportTmp.Balance06 + metCustAgingReportTmp.Balance07 );

            metCustAgingReportTmp.update();
            ttscommit;
        }
    }
